  person_h := person_facts_h;

  stress_1 := []: ℤ[];
  stress_h := []: 𝔹[];
  // 0.3::stress(X) :- person(X).
  for k7 in [0..person_h.length) {
    X := person_1[k7];
    x8 := person_h[k7];
    c9 := flip(0.3);
    v10 := x8 && c9;
    f11 := false;
    for k12 in [0..stress_h.length) {
      if stress_1[k12] == X { stress_h[k12] = stress_h[k12] || v10; f11 = true; }
    }
    if !f11 { stress_1 = stress_1 ~ [X]; stress_h = stress_h ~ [v10]; }
  }

  // smokes/1: recursive; the rules applied in stages from no tuple,
  // each reading the stage before, until a stage adds no tuple and the stages number the tuples
  smokes_1 := []: ℤ[];
  smokes_h := []: 𝔹[];
  stage13 := 0;
  before14 := -1;
  while stage13 < smokes_h.length || smokes_h.length != before14 {
    before14 = smokes_h.length;
    next_smokes_1 := []: ℤ[];
    next_smokes_h := []: 𝔹[];
    // smokes(X) :- stress(X).
    for k15 in [0..stress_h.length) {
      X := stress_1[k15];
      x16 := stress_h[k15];
      v17 := x16;
      f18 := false;
      for k19 in [0..next_smokes_h.length) {
        if next_smokes_1[k19] == X { next_smokes_h[k19] = next_smokes_h[k19] || v17; f18 = true; }
      }
      if !f18 { next_smokes_1 = next_smokes_1 ~ [X]; next_smokes_h = next_smokes_h ~ [v17]; }
    }
    // smokes(X) :- friend(X,Y), influences(Y,X), smokes(Y).
    for k20 in [0..friend_h.length) {
      X := friend_1[k20];
      Y := friend_2[k20];
      x21 := friend_h[k20];
      for k22 in [0..influences_h.length) {
        if influences_1[k22] == Y && influences_2[k22] == X {
          x23 := influences_h[k22];
          for k24 in [0..smokes_h.length) {
            if smokes_1[k24] == Y {
              x25 := smokes_h[k24];
              v26 := x21 && x23 && x25;
              f27 := false;
              for k28 in [0..next_smokes_h.length) {
                if next_smokes_1[k28] == X { next_smokes_h[k28] = next_smokes_h[k28] || v26; f27 = true; }
              }
              if !f27 { next_smokes_1 = next_smokes_1 ~ [X]; next_smokes_h = next_smokes_h ~ [v26]; }
            }
          }
        }
      }
    }
    smokes_1 = next_smokes_1;
    smokes_h = next_smokes_h;
    stage13 = stage13 + 1;
  }

  q29 := false;
  for q29_k in [0..smokes_h.length) { if smokes_1[q29_k] == 1000000 { q29 = smokes_h[q29_k]; } }
  q30 := false;
  for q30_k in [0..smokes_h.length) { if smokes_1[q30_k] == 1000001 { q30 = smokes_h[q30_k]; } }
  q31 := false;
  for q31_k in [0..smokes_h.length) { if smokes_1[q31_k] == 1000002 { q31 = smokes_h[q31_k]; } }
  q32 := false;
  for q32_k in [0..smokes_h.length) { if smokes_1[q32_k] == 1000003 { q32 = smokes_h[q32_k]; } }
