  var size = sum(map(function(r) { return _.size(r); }, rels));
  return stage < size || size !== before ? stages_smokes(stage_smokes(rels), stage + 1, size) : rels;
};
var rels_smokes = stages_smokes([{}], 0, -1);
var smokes = rels_smokes[0];

// component 0 bool
// component 1 bool
// component 2 bool
// component 3 bool
// component 4 bool
// component 5 bool
// component 6 bool
// component 7 bool
var model = function() {
  return [holds(smokes, ['p1'])(),
          holds(smokes, ['p2'])(),
          holds(smokes, ['p3'])(),
          holds(smokes, ['p4'])(),
          holds(smokes, ['p5'])(),
          holds(smokes, ['p6'])(),
          holds(smokes, ['p7'])(),
          holds(smokes, ['p8'])()];
};
Infer({method: 'enumerate'}, model);

