  q34 := false;
  for q34_k in [0..smokes_h.length) { if smokes_1[q34_k] == 1000010 { q34 = smokes_h[q34_k]; } }
  q35 := false;
  for q35_k in [0..smokes_h.length) { if smokes_1[q35_k] == 1000011 { q35 = smokes_h[q35_k]; } }
  q36 := false;
  for q36_k in [0..smokes_h.length) { if smokes_1[q36_k] == 1000012 { q36 = smokes_h[q36_k]; } }
  q37 := false;
