  for q42_k in [0..smokes_h.length) { if smokes_1[q42_k] == 1000005 { q42 = smokes_h[q42_k]; } }
  queries := [q29, q30, q31, q32, q33, q34, q35, q36, q37, q38, q39, q40, q41, q42];
  return queries[7];
}

